# Niveau HSK 4 (chinois, HSK 2.0 niveau 4) : 8 étapes dans l'empire de Qin, leçons et examen blanc (français + anglais).
# Mode histoire : scribe du chancelier Li Si, chargé d'unifier l'écriture de l'empire (voir gen-story.py).
# Écrit aussi la section HSK 4 de l'onglet Hanzi.
# Usage : python3 scripts/hsk4-level.py   (après les niveaux HSK 1 à 3)
from zh_common import *

# Slugs déjà pris par un autre niveau : suffixe « -h4 » (le même mot peut exister en japonais, coréen…).
_TAKEN = set()
for _p in ALL_LEVELS + HSK_PATHS[:3]:
    for _it in items_of(json.load(open(os.path.join(ROOT, _p), encoding='utf-8'))):
        _TAKEN.add(_it['slug'])
for _th in json.load(open(os.path.join(ROOT, 'content/expressions/expressions.json'), encoding='utf-8'))['themes']:
    _TAKEN.update(_e['slug'] for _e in _th['expressions'])
def _free(full):
    return full + '-h4' if full in _TAKEN else full
_Z, _ZG, _H = Z, ZG, H
def Z(slug, *a): return {**_Z(slug, *a), 'slug': _free('zh-' + slug)}
def ZG(slug, *a): return {**_ZG(slug, *a), 'slug': _free('gram-zh-' + slug)}
def H(slug, *a): return {**_H(slug, *a), 'slug': _free('hz-' + slug)}

