        FB(COMPLETE, '我真＿没有早点儿学汉语。', ['后悔', '羡慕', '感动'], '后悔', ('Regretter : 后悔.', 'To regret: 后悔.'), ('Je regrette vraiment de ne pas avoir appris le chinois plus tôt.', 'I really regret not learning Chinese earlier.')),
        DC(ANSWER, [('朋友', '明天就要面试了，你紧张吗？')], ('Un ami demande si l’entretien de demain te stresse (un peu, mais tu es prêt).', 'A friend asks if you’re nervous about tomorrow’s interview (a little, but you’re ready).'), ['有点儿紧张，不过我准备好了。', '我很羡慕你。', '太无聊了。'], '有点儿紧张，不过我准备好了。', ('Stressé : 紧张.', 'Nervous: 紧张.')),
